Here is a sample function in C# that maps a distance value between 200 and 300 to the range of 0 to 1:

```c#
float MapDistanceToRange(float distance)
{
    // Check if distance value is within bounds
    if (distance < 200f || distance > 300f)
    {
        Debug.LogError("Distance value is out of range.");
        return 0f;
    }

    // Map distance value to 0-1 range
    float mappedValue = (distance - 200f) / 100f;

    return mappedValue;
}
